// See modes/status_screen.hpp. The drawing code is the reference renderer from
// the design card (SPEC.md), unchanged: the mockups it produced are the spec,
// so every constant below is a decision that was measured, not a taste.
#include "modes/status_screen.hpp"

#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

namespace hgp {
namespace {

using namespace layout;

constexpr uint16_t kInk = hg::rgb565(0, 0, 0);
constexpr uint16_t kPaper = hg::rgb565(255, 255, 255);

// ---------------------------------------------------------------- icon bytes
// Generated by the design card's tools/icons.py. MSB first, rows padded to a
// byte. Glyph strokes are 1 px; a state overlay (the cut) is 2 px so it reads
// as a mark laid over the glyph rather than as part of it.
constexpr int kWifiW = 16, kWifiH = 15;
const uint8_t kWifiUp[] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, 0xc0, 0x0e, 0x70,
    0x30, 0x0c, 0x20, 0x04, 0x07, 0xe0, 0x08, 0x10, 0x00, 0x00, 0x00, 0x00,
    0x01, 0x80, 0x01, 0x80, 0x01, 0x80,
};

const uint8_t kWifiCut[] = {
    0x80, 0x00, 0xc0, 0x00, 0xe0, 0x00, 0x78, 0x00, 0x3d, 0xc0, 0x1e, 0x70,
    0x2f, 0x0c, 0x23, 0x84, 0x05, 0xc0, 0x08, 0xf0, 0x00, 0x78, 0x00, 0x3c,
    0x01, 0x9e, 0x01, 0x87, 0x01, 0x83,
};

constexpr int kBtW = 12, kBtH = 16;
const uint8_t kBtUp[] = {
    0x04, 0x00, 0x07, 0x00, 0x05, 0x80, 0x04, 0xc0, 0x04, 0x60, 0x04, 0xc0,
    0x67, 0x00, 0x3c, 0x00, 0x3c, 0x00, 0x67, 0x00, 0x04, 0xc0, 0x04, 0x60,
    0x04, 0xc0, 0x05, 0x80, 0x07, 0x00, 0x04, 0x00,
};

const uint8_t kBtCut[] = {
    0x84, 0x00, 0xc7, 0x00, 0xe5, 0x80, 0x74, 0xc0, 0x34, 0x60, 0x18, 0xc0,
    0x7d, 0x00, 0x2e, 0x00, 0x37, 0x00, 0x63, 0x80, 0x05, 0x80, 0x04, 0xc0,
    0x04, 0xe0, 0x05, 0x70, 0x07, 0x30, 0x04, 0x10,
};

// ------------------------------------------------------------------ helpers
void bitmap(hg::Canvas& c, int x, int y, int w, int h, const uint8_t* bits) {
  c.bitmap1(x, y, w, h, bits, kInk);
}

int cols(std::string_view s) { return static_cast<int>(hg::font::length(s)); }

// Right-aligns an icon so its right edge lands on `right`.
int right_at(int right, int w) { return right - w; }

// ------------------------------------------------------------------ battery
// 1 px described line between two points, used for the bolt and the "?".
void seg(hg::Canvas& c, int x0, int y0, int x1, int y1) {
  int dx = x1 > x0 ? x1 - x0 : x0 - x1;
  int dy = y1 > y0 ? y1 - y0 : y0 - y1;
  int sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
  int err = dx - dy;
  for (;;) {
    c.pixel(x0, y0, kInk);
    if (x0 == x1 && y0 == y1) break;
    int e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x0 += sx; }
    if (e2 < dx) { err += dx; y0 += sy; }
  }
}

constexpr int kBattW = 28, kBattH = 15;

void draw_battery(hg::Canvas& c, int right, int cy, const StatusView& v) {
  const int x = right_at(right, kBattW);
  const int y = cy - kBattH / 2;

  // Body: 26 px shell plus a 2 px terminal nub, every line exactly 1 px.
  c.fill_rect(x, y, kBattW - 2, 1, kInk);               // top
  c.fill_rect(x, y + kBattH - 1, kBattW - 2, 1, kInk);  // bottom
  c.fill_rect(x, y, 1, kBattH, kInk);                   // left
  c.fill_rect(x + kBattW - 3, y, 1, kBattH, kInk);      // right
  c.fill_rect(x + kBattW - 2, y + 5, 2, 5, kInk);       // terminal nub

  if (v.external_power) {
    // The board has no charge-status line, so a bolt means "external power is
    // present", not "the cell is charging". Keep the percentage in the footer:
    // the bolt replaces the level because two messages do not fit in 21 px.
    seg(c, x + 13, y + 2, x + 7, y + 8);
    seg(c, x + 7, y + 8, x + 12, y + 8);
    seg(c, x + 12, y + 8, x + 9, y + 13);
    return;
  }
  if (v.battery_pct < 0) {
    // Unknown: an empty shell plus a "?", so it never reads as "0%".
    seg(c, x + 9, y + 3, x + 14, y + 3);
    seg(c, x + 14, y + 3, x + 14, y + 6);
    seg(c, x + 14, y + 6, x + 11, y + 8);
    seg(c, x + 11, y + 8, x + 11, y + 9);
    c.fill_rect(x + 10, y + 11, 2, 2, kInk);
    return;
  }
  const int lvl = v.battery_pct > 100 ? 100 : v.battery_pct;
  const int fill = lvl * 21 / 100;  // 21 px of usable interior
  if (fill > 0) c.fill_rect(x + 3, y + 2, fill, kBattH - 4, kInk);
}

// --------------------------------------------------------------- masthead
void draw_masthead(hg::Canvas& c, const StatusView& v) {
  // Centre the icons on the clock's GLYPH (21 px tall), not its line box (27 px):
  // the line box carries 6 px of leading below the glyph, which would push every
  // icon 3 px low against the rule.
  const int cy = kMastheadTop + (hg::font::kGlyphHeight * kScaleTime) / 2;

  // Clock. "--:--" when the clock is unset: a blank slot reads as a bug, and a
  // spinner is meaningless on a panel that only updates on change.
  char clock[8];
  if (v.time_valid) std::snprintf(clock, sizeof clock, "%02d:%02d", v.hour, v.minute);
  else std::snprintf(clock, sizeof clock, "--:--");
  c.text(kMarginX, kMastheadTop, clock, kScaleTime, kInk);

  // Icons, right to left. A slot is reserved whether or not it draws, so the
  // layout never shifts between states.
  draw_battery(c, kRightEdge, cy, v);
  const int wifiRight = kRightEdge - kBattW - 10;
  // Both link slots always draw. A missing icon reads as a rendering fault; the
  // cut mark reads as "this link is not up", which is the only fact the user
  // needs. The words in the hero and footer carry the precise reason.
  const uint8_t* wifiBits = v.wifi == WifiState::Online ? kWifiUp : kWifiCut;
  bitmap(c, right_at(wifiRight, kWifiW), cy - kWifiH / 2, kWifiW, kWifiH, wifiBits);
  const int btRight = wifiRight - kWifiW - 10;
  const uint8_t* btBits = v.bt == BtState::Connected ? kBtUp : kBtCut;
  bitmap(c, right_at(btRight, kBtW), cy - kBtH / 2, kBtW, kBtH, btBits);
}

// --------------------------------------------------------------- the words
// A percentage and one fact, in 14 columns. The fact never gets truncated: the
// level is what is dropped when both do not fit, because the masthead icon
// still carries the level and "2 QUEUED" is the line a user acts on.
std::string footer(const StatusView& v, std::string_view fact) {
  const std::string pct = v.battery_pct >= 0 ? std::to_string(v.battery_pct) + "%" : std::string("NO BATTERY");
  if (fact.empty()) return pct;
  const std::string both = pct + " \xC2\xB7 " + std::string(fact);
  if (cols(both) <= kFootCols) return both;
  // "100%" plus a word is one column too long. The masthead's bolt already says
  // external power, so that fact gives way to the level; a count or a fault is
  // worth more than the level and keeps the line.
  if (fact == "ON POWER") return pct;
  if (cols(fact) <= kFootCols) return std::string(fact);
  return pct;
}

// "12 s" / "1:05": a note's length, the only duration the copy prints.
std::string duration(uint32_t seconds) {
  char buf[16];
  if (seconds < 60) std::snprintf(buf, sizeof buf, "%u s", static_cast<unsigned>(seconds));
  else std::snprintf(buf, sizeof buf, "%u:%02u", static_cast<unsigned>(seconds / 60), static_cast<unsigned>(seconds % 60));
  return buf;
}

// "443 KB" / "1.2 MB": the WAV on the card, rounded for reading.
std::string size_text(uint32_t bytes) {
  char buf[16];
  if (bytes >= 1024u * 1024u) std::snprintf(buf, sizeof buf, "%.1f MB", bytes / (1024.0 * 1024.0));
  else if (bytes >= 1024u) std::snprintf(buf, sizeof buf, "%u KB", static_cast<unsigned>((bytes + 512) / 1024));
  else std::snprintf(buf, sizeof buf, "%u B", static_cast<unsigned>(bytes));
  return buf;
}

}  // namespace

std::string status_fit(std::string_view s, int cols) {
  if (static_cast<int>(hg::font::length(s)) <= cols) return std::string(s);
  if (cols <= 2) return std::string(s.substr(0, hg::font::prefix(s, static_cast<size_t>(cols))));
  return std::string(s.substr(0, hg::font::prefix(s, static_cast<size_t>(cols - 2)))) + "..";
}

StatusView compose_status(const StatusInputs& in) {
  StatusView v;
  v.time_valid = in.time_valid;
  v.hour = in.hour;
  v.minute = in.minute;
  v.wifi = in.link_online ? WifiState::Online : in.network_up ? WifiState::Connecting : WifiState::Offline;
  v.bt = !in.bt_supported         ? BtState::Unsupported
         : in.bt_connected        ? BtState::Connected
         : in.bt_paired           ? BtState::Disconnected
                                  : BtState::Off;
  v.battery_pct = in.battery_pct;
  v.external_power = in.external_power;

  char note[96];
  // The order is the user's: what is happening now, then what is broken, then
  // the link, then the cell, then the clock, then the notes.
  if (in.notes == NotesPhase::Recording) {
    const uint32_t s = in.recording_s;
    std::snprintf(note, sizeof note, "%02u:%02u  tap PWR to stop", static_cast<unsigned>(s / 60),
                  static_cast<unsigned>(s % 60));
    v.hero = "RECORDING";
    v.note = note;
    v.foot = footer(v, in.external_power ? "ON POWER" : "");
  } else if (in.notes == NotesPhase::Uploading) {
    if (in.uploading_valid)
      std::snprintf(note, sizeof note, "note %02d:%02d  \xC2\xB7  %s", in.uploading_hour, in.uploading_minute,
                    size_text(in.uploading_bytes).c_str());
    else
      std::snprintf(note, sizeof note, "note  \xC2\xB7  %s", size_text(in.uploading_bytes).c_str());
    v.hero = "UPLOADING";
    v.note = note;
    v.foot = footer(v, in.pending > 1 ? "1 OF " + std::to_string(in.pending) : "");
  } else if (in.notes == NotesPhase::Error || !in.error.empty()) {
    v.error = true;
    v.hero = "ERROR";
    v.note = in.error.empty() ? std::string("Something went wrong. See the log.") : in.error;
    v.foot = footer(v, in.sd_ready ? "" : "NO CARD");
  } else if (!in.sd_ready) {
    // No card is the one fault the mode cannot recover from on its own, and it
    // is not an "error" in the sense of a failed action: it is a missing part.
    v.error = true;
    v.hero = "NO CARD";
    v.note = "Recording needs a card. Anything on it is safe.";
    v.foot = footer(v, "NO CARD");
  } else if (v.wifi != WifiState::Online) {
    v.hero = "OFFLINE";
    v.note = "Notes save to the card, upload when back";
    v.foot = footer(v, in.pending ? std::to_string(in.pending) + " QUEUED" : "");
  } else if (in.battery_pct >= 0 && in.battery_pct <= 20 && !in.external_power) {
    v.hero = "LOW POWER";
    v.note = "Plug in soon. Recording stops if it dies.";
    v.foot = footer(v, "");
  } else if (!in.time_valid) {
    v.hero = "NO TIME";
    v.note = "The clock sets itself once online.";
    v.foot = footer(v, "");
  } else if (!in.has_newest) {
    v.hero = "NO NOTES";
    v.note = "Hold PWR and speak to record one.";
    v.foot = footer(v, in.external_power ? "ON POWER" : "");
  } else {
    char hero[24];
    std::snprintf(hero, sizeof hero, "%u NOTE%s", static_cast<unsigned>(in.stored), in.stored == 1 ? "" : "S");
    v.hero = status_fit(hero, kHeroCols);
    if (in.newest_valid)
      std::snprintf(note, sizeof note, "Newest note %02d:%02d, %s. Tap PWR to add another.", in.newest_hour,
                    in.newest_minute, duration(in.newest_duration_s).c_str());
    else
      // The note's own stamp is not a time (it was recorded before the clock
      // was ever set), so the line prints only what is true: the length. It
      // used to say "no clock yet", which contradicted a clock already on the
      // masthead (the hardware QA's D5).
      std::snprintf(note, sizeof note, "Newest note, %s. Tap PWR to add another.",
                    duration(in.newest_duration_s).c_str());
    v.note = note;
    v.foot = footer(v, in.pending                  ? std::to_string(in.pending) + " QUEUED"
                      : in.external_power        ? "ON POWER"
                      : in.synced               ? "SYNCED"
                                                : "");
  }
  v.hero = status_fit(v.hero, kHeroCols);
  v.foot = status_fit(v.foot, kFootCols);
  return v;
}

StatusView compose_pairing(const StatusInputs& in, const PairingCopy& copy) {
  // The chrome (clock, links, cell) is the resting face's; only the words are
  // the pairing screen's.
  StatusView v = compose_status(in);
  v.error = false;
  v.hero = copy.code.empty() ? std::string("PAIRING") : copy.code;
  std::string note;
  // One paragraph: the renderer wraps by column, and the 5x7 font has no
  // glyph for a newline.
  for (const std::string* line : {&copy.headline, &copy.detail, &copy.hint}) {
    if (line->empty()) continue;
    if (!note.empty()) note += ' ';
    note += *line;
  }
  if (note.empty()) note = "Waiting for the Hermes host.";
  v.note = note;
  v.hero = status_fit(v.hero, layout::kHeroCols);
  return v;
}

void render_status(hg::Canvas& c, const StatusView& v) {
  c.fill_rect(0, 0, kW, kH, kPaper);
  draw_masthead(c, v);

  // Hairline: the only rule on the screen. It separates chrome from content and
  // gives the eye a hard edge to land on without a filled bar.
  c.fill_rect(kMarginX, kRuleY, kRightEdge - kMarginX, 1, kInk);

  // Hero: the device state. Short by construction (the copy's phase words are
  // all <= 9 columns), so scale 3 always fits.
  const std::string hero = status_fit(v.hero, kHeroCols);
  if (v.error) {
    // Error is the one state that earns a box: it must look different from
    // "idle with a word" at a glance, and it is rare enough to spend the ink.
    const int tw = hg::Canvas::text_width(hero, kScaleHero);
    c.rect(kMarginX - 4, kHeroTop - 4, tw + 8, 7 * kScaleHero + 8, kInk);  // 3 px pad all round
  }
  c.text(kMarginX, kHeroTop, hero, kScaleHero, kInk);

  // Note block: a 3 px spine, then the note wrapped at body scale.
  std::vector<std::string> lines = hg::wrap_text(v.note, kNoteCols);
  bool more = false;
  if (static_cast<int>(lines.size()) > kNoteMaxLines) {
    lines.resize(kNoteMaxLines);
    more = true;
  }
  if (lines.empty()) lines.push_back("");
  const int spineH = (static_cast<int>(lines.size()) - 1) * hg::Canvas::line_height(kScaleBody) + 14;
  if (!v.note.empty()) c.fill_rect(kSpineX, kNoteTop - 1, kSpineW, spineH, kInk);
  for (size_t i = 0; i < lines.size(); ++i) {
    std::string s = lines[i];
    // The 5x7 font has no U+2026 glyph (it draws "?"), so overflow is marked
    // with ASCII ".." by status_fit(), the same marker the SDK uses elsewhere.
    if (more && i + 1 == lines.size()) s = status_fit(s + "..", kNoteCols);
    c.text(kNoteTextX, kNoteTop + static_cast<int>(i) * hg::Canvas::line_height(kScaleBody), s, kScaleBody, kInk);
  }

  // Footer: one line of truth. Carries the battery percentage that does not fit
  // in the masthead, and the count or link state that does not fit in the hero.
  if (!v.foot.empty()) c.text(kMarginX, kFootTop, status_fit(v.foot, kFootCols), kScaleBody, kInk);
}

namespace {

void mix(uint32_t& h, const void* data, size_t len) {
  const auto* p = static_cast<const uint8_t*>(data);
  for (size_t i = 0; i < len; ++i) {
    h ^= p[i];
    h *= 16777619u;  // FNV-1a
  }
}

void mix_string(uint32_t& h, const std::string& s) {
  const uint32_t len = static_cast<uint32_t>(s.size());
  mix(h, &len, sizeof len);
  mix(h, s.data(), s.size());
}

}  // namespace

uint32_t StatusScreen::signature(const StatusView& v) {
  uint32_t h = 2166136261u;
  const uint8_t flags = static_cast<uint8_t>((v.time_valid ? 1 : 0) | (v.external_power ? 2 : 0) | (v.error ? 4 : 0));
  mix(h, &flags, sizeof flags);
  mix(h, &v.hour, sizeof v.hour);
  mix(h, &v.minute, sizeof v.minute);
  const uint8_t links = static_cast<uint8_t>(static_cast<int>(v.wifi) | (static_cast<int>(v.bt) << 2));
  mix(h, &links, sizeof links);
  mix(h, &v.battery_pct, sizeof v.battery_pct);
  mix_string(h, v.hero);
  mix_string(h, v.note);
  mix_string(h, v.foot);
  return h;
}

bool StatusScreen::draw(hg::Display& display, const StatusView& v, bool force) {
  const uint32_t sig = signature(v);
  // An e-paper refresh is a visible half second: an identical view is not worth
  // one, and the caller's frame is already the right one.
  if (!force && valid_ && sig == sig_) return true;
  const hg::DisplayInfo info = display.info();
  if (!display.framebuffer() || info.width < kW || info.height < kH) return false;
  hg::Canvas c(display.framebuffer(), info.width, info.height, info.swap_bytes);
  render_status(c, v);
  display.flush(0, static_cast<uint16_t>(kH));
  sig_ = sig;
  valid_ = true;
  return true;
}

}  // namespace hgp
